'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function distance(a, b) {
  let row = new Array(b.length + 1).fill(0);
  for (const line of a) {
    const next = [0];
    for (let j = 0; j < b.length; j++) {
      next.push(line === b[j] ? row[j] + 1 : Math.max(row[j + 1], next[j]));
    }
    row = next;
  }
  return a.length + b.length - 2 * row[b.length];
}
function check(a, b, contexts) {
  Object.freeze(a);
  Object.freeze(b);
  const script = diffLines(a, b);
  assert.deepEqual(script.filter(e => e.op !== 'insert').map(e => e.line), a);
  assert.deepEqual(script.filter(e => e.op !== 'delete').map(e => e.line), b);
  assert.equal(script.filter(e => e.op !== 'equal').length, distance(a, b));
  let inserting = false;
  for (const e of script) {
    if (e.op === 'equal') inserting = false;
    else if (e.op === 'insert') inserting = true;
    else { assert.equal(e.op, 'delete'); assert.equal(inserting, false); }
  }
  assert.deepEqual(diffLines(a, b), script);
  for (const context of contexts) {
    const hunks = unifiedHunks(a, b, { context });
    for (const h of hunks) { Object.freeze(h.lines); Object.freeze(h); }
    Object.freeze(hunks);
    assert.deepEqual(applyHunks(a, hunks), b);
    if (a.length === b.length && a.every((line, i) => line === b[i])) {
      assert.deepEqual(hunks, []);
    }
  }
}

