    [['x', 'a'], ['a'], { oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-x'] }],
    [['a', 'x'], ['a'], { oldStart: 2, oldLines: 1, newStart: 1, newLines: 0, lines: ['-x'] }],
    [['a', 'x', 'b'], ['a', 'b'], { oldStart: 2, oldLines: 1, newStart: 1, newLines: 0, lines: ['-x'] }],
  ];
  for (const [a, b, hunk] of cases) {
    assert.deepEqual(unifiedHunks(a, b, { context: 0 }), [hunk]);
    assert.deepEqual(applyHunks(a, [hunk]), b);
  }
  const a = ['a'];
  assert.notEqual(applyHunks(a, []), a);
  assert.deepEqual(unifiedHunks(a, a), []);
});

test('context touching merges, separated regions retain global offsets', () => {
  assert.deepEqual(unifiedHunks(['a', 'b', 'c', 'd'], ['x', 'b', 'c', 'y'], { context: 1 }), [{
    oldStart: 1, oldLines: 4, newStart: 1, newLines: 4,
    lines: ['-a', '+x', ' b', ' c', '-d', '+y'],
  }]);
  const a = ['a', 'b', 'c', 'd', 'e', 'f', 'g'];
  const b = ['x', 'y', 'b', 'c', 'd', 'e', 'g'];
  const hunks = unifiedHunks(a, b, { context: 1 });
  assert.deepEqual(hunks, [
    { oldStart: 1, oldLines: 2, newStart: 1, newLines: 3, lines: ['-a', '+x', '+y', ' b'] },
    { oldStart: 5, oldLines: 3, newStart: 6, newLines: 2, lines: [' e', '-f', ' g'] },
  ]);
  assert.deepEqual(applyHunks(a, hunks), b);
  assert.deepEqual(applyHunks(['a'], [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+x'] },
    { oldStart: 0, oldLines: 0, newStart: 2, newLines: 1, lines: ['+y'] },
  ]), ['x', 'y', 'a']);
});

test('malformed hunks, mismatches, overlaps, and coordinate disagreement throw indexed errors', () => {
  const valid = { oldStart: 1, oldLines: 1, newStart: 1, newLines: 1, lines: ['-a', '+x'] };
  const invalid = [null, {}, { ...valid, oldStart: -1 }, { ...valid, oldStart: 0 },
    { ...valid, oldStart: 4 }, { ...valid, oldStart: 1.5 }, { ...valid, newStart: 0 },
    { ...valid, newStart: 2 }, { ...valid, oldLines: -1 }, { ...valid, oldLines: 2 },
    { ...valid, newLines: 2 }, { ...valid, newLines: 0 }, { ...valid, lines: ['-z', '+x'] },
    { ...valid, lines: [' a', '+x'] }, { ...valid, lines: ['?a'] },
    { ...valid, lines: [''] }, { ...valid, lines: [null] }, { ...valid, lines: ' a' },
    { ...valid, lines: ['-a', '-b', '+x'] }, { ...valid, oldLines: Infinity },
    { ...valid, lines: new Array(1) },
  ];
  for (const h of invalid) assert.throws(() => applyHunks(['a', 'b'], [h]), /hunk 0 does not apply/);
  assert.throws(() => applyHunks(['a', 'b'], [valid, valid]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(['a', 'b'], [
    { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: [' b'] }, valid,
  ]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(['a', 'b'], [valid, {
    oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: [' wrong'],
  }]), /hunk 1 does not apply/);
});

test('small edits on 20,000 lines, including repetitive inputs, stay well below one second', () => {
  for (const repetitive of [false, true]) {
    const a = Array.from({ length: 20000 }, (_, i) => repetitive ? 'same' : `line ${i}`);
    const b = a.slice();
    b.splice(18000, 1);
    b.splice(10000, 1, '-replacement');
    b.splice(100, 0, '+inserted');
    const start = performance.now();
    const script = diffLines(a, b);
    const hunks = unifiedHunks(a, b);
    assert.deepEqual(applyHunks(a, hunks), b);
    const elapsed = performance.now() - start;
    assert.equal(script.filter(e => e.op !== 'equal').length, 4);
    assert.ok(elapsed < 500, `elapsed ${elapsed} ms`);
    console.log(`${repetitive ? 'repetitive' : 'unique'} 20,000-line diff + hunks + application: ${elapsed.toFixed(2)} ms`);
  }
});
